#!/usr/bin/env python3
from pathlib import Path
import base64

FILES = [('README.md', ''), ('docs/IO_CONTRACT.md', ''), ('src/dada_4bar_synthesis/__init__.py', ''), ('src/dada_4bar_synthesis/contracts.py', ''), ('src/dada_4bar_synthesis/io.py', ''), ('tests/test_motion_target_io.py', '')]

for name, payload in FILES:
    path = Path(name)
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_bytes(base64.b64decode(payload))
    print(f"updated {path}")

print("\nRun: pytest")
